                (u == msg.sender || uAfter == uBefore) &&
                c.getBalance(msg.sender) == 0
            );
        } else {
            assert(otherAfter == otherBefore && uAfter == uBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address other, uint amount) public payable {
        require(other != address(this));
        require(address(this).balance >= amount);
        c.addToBalance{value: amount}();
        uint otherBefore = c.getBalance(other);
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint otherAfter = c.getBalance(other);
        assert(reverted || (otherAfter == otherBefore && c.getBalance(address(this)) == 0));
    }

    receive() external payable {}
}
